head.script:
// 테스트 설명, 유효성 값 설정
//  분리 초점 : GroupBy 기능이 적용되면 (1) Header 클릭 정렬 미동작 (2) 기존 Filter 미동작 (3) 그룹핑된 Column 에 Group FilterList 적용
scwin.tData = {
    "description" : "[gridView > P > groupbyZone]<br/>GridView 컴포넌트의 상단에 GroupBy Zone 을 표시할지 설정합니다.",
    "validation" : [
        "GroupBy 기능이 적용되면 Header 클릭에 의한 정렬 기능이 동작하지 않습니다.",
        "GroupBy 기능이 적용되면 기존에 설정한 Filter 기능이 동작하지 않습니다.",
        "groupbyZone=true 이면 그룹핑된 Column 에 Group FilterList 기능이 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    scwin.comp_init();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : groupbyZone=true + sortable=true(sortEvent=ondblclick) 고정
scwin.comp_init = async function () {
    if (typeof dlt_bind !== 'undefined') { $p.data.remove("dlt_bind"); }
    if (typeof target1 !== 'undefined') { target1.remove(); }

    scwin._grouped = false;

    $c.gcm.createLabel('label="[전제] groupbyZone=true + sortable=true(Header 더블클릭 정렬) + 지역 Column 필터 버튼(아이콘)\n[정렬] (1) 그룹핑 전 값 Header 더블클릭 → 정렬 동작(순서 변함) (2) 지역 Header 를 Zone 으로 드래그하여 그룹핑 (3) 그룹핑 후 Header 더블클릭 → 정렬 미동작(순서 그대로)\n[필터] (1) 그룹핑 전 지역 Header 의 필터 버튼 클릭 → 목록에서 부산 체크 해제(서울만) → 표시행 감소(필터 동작) (2) 지역을 Zone 으로 드래그하여 그룹핑하면 그 필터가 해제되어 전체 표시(필터 미동작). [그룹핑 확인] 버튼으로 표시 데이터행 수/화면순서 확인\n[Group FilterList] 그룹핑 후 Zone 의 그룹 Column chip 을 클릭하면 Group FilterList(체크박스 목록)가 표시됨"', '', 'label1');

    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    scwin.fillData();

    await scwin.createGridView();
}



scwin.fillData = function () {
    let rows = [
        { col1: "부산", col2: "영업", col3: "B", col4: 30 },
        { col1: "서울", col2: "개발", col3: "A", col4: 10 },
        { col1: "부산", col2: "개발", col3: "B", col4: 50 },
        { col1: "서울", col2: "영업", col3: "A", col4: 20 },
        { col1: "서울", col2: "개발", col3: "B", col4: 40 },
        { col1: "부산", col2: "영업", col3: "A", col4: 60 }
    ];
    dlt_bind.setJSON(rows, false);
}



// gridView 동적 생성 (groupbyZone=true, sortable=true, sortEvent=ondblclick + ongroupby 핸들러)
scwin.createGridView = async function () {
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    let cList = $c.gcm.createCList({ groupbyZone: true, sortable: "true", sortEvent: "ondblclick", useFilterList: "true", showSortableImage: "true", showSortableUseFilter: "true" });

    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' id="" dataList="data:dlt_bind" ev:ongroupby="scwin.target1_ongroupby" style="width:600px;height:460px;">';
    s += '<w2:caption style="" id="caption1" value="groupbyZone 강제변경 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="130" style="" inputType="text" id="hcol1" value="지역" useFilter="true"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="hcol2" value="부서"></w2:column>';
    s += '<w2:column width="90" style="" inputType="text" id="hcol3" value="등급"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="hcol4" value="값"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="130" style="" inputType="text" id="col1"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="col2"></w2:column>';
    s += '<w2:column width="90" style="" inputType="text" id="col3"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);

    // Header 더블클릭 관찰 리스너 : 사용자가 헤더를 직접 더블클릭한 시점의 화면 순서를 출력
    //  - 그룹핑 전 : sortEvent=ondblclick 로 정렬 동작(순서 바뀜) / 그룹핑 후 : 정렬 미동작(순서 그대로)
    let headTable = document.getElementById(target1.id + "_head_table");
    if (headTable) headTable.addEventListener("dblclick", scwin.onHeaderDblclick);

    // GroupBy Zone 클릭 관찰 리스너 : 사용자가 그룹 Column chip 을 클릭한 시점의 Group FilterList 표시 여부를 출력
    //  - chip 클릭 시 엔진이 Group FilterList(w2grid_groupbyZone_list) 팝업을 토글 → setTimeout(…,0) 후 표시 상태 실측
    let zoneDiv = document.getElementById(target1.id + "_groupbyZone_div");
    if (zoneDiv) zoneDiv.addEventListener("click", scwin.onGroupbyZoneClick);
}



// GroupBy Zone 그룹 Column chip 클릭 관찰 : Group FilterList 팝업 표시 여부를 결과창에 출력
//  - chip(.w2grid_groupbyZone_column) 클릭에만 반응(디바운스 1회), setTimeout(…,0) 으로 엔진 토글 처리 후 실측
//  - 실측 셀렉터 : Group FilterList 목록 요소 .w2grid_groupbyZone_list (display/height 로 표시 여부 판정)
scwin.onGroupbyZoneClick = function (e) {
    let el = e.target, isChip = false;
    while (el && el !== document) {
        if (el.className && typeof el.className === 'string' && el.className.indexOf('w2grid_groupbyZone_column') >= 0) { isChip = true; break; }
        el = el.parentNode;
    }
    if (!isChip) return;

    let now = Date.now();
    if (scwin._lastZoneClick && (now - scwin._lastZoneClick) < 150) return;
    scwin._lastZoneClick = now;

    setTimeout(function () {
        let list = document.querySelector(".w2grid_groupbyZone_list");
        let shown = false;
        if (list) {
            let cs = window.getComputedStyle(list);
            let r = list.getBoundingClientRect();
            shown = cs.display !== 'none' && cs.visibility !== 'hidden' && r.height > 0;
        }
        wf_body_bottom.getObj("scwin").setReturnValue("[Group FilterList] 그룹 Column chip 클릭 → FilterList " + (shown ? "표시됨" : "미표시"));
    }, 0);
}



// ongroupby : 지역 헤더를 Zone 으로 드래그하면 발생 → 그룹핑 적용
scwin.target1_ongroupby = function (options) {
    options.groupbyHeader = [
        { inputType: "expression", expression: "toggle() + depthStr()", colSpan: 4, align: "left" }
    ];
    options.hideFooter = true;
    target1.groupby(options);
    wf_body_bottom.getObj("scwin").setReturnValue("[ongroupby 발생] GroupBy 가 적용되었습니다.");
}



// depth 계층 가시화 들여쓰기 : depth×2칸 순수 공백
scwin._depthMark = function (depth) { return "  ".repeat(depth); };

// 화면(tbody) 렌더 Row 를 화면 순서(위→아래) 그대로 순회하여 표시 텍스트 반환 (_1/_5 출력 형식과 통일)
//  - 그룹 행 : 그룹 셀 텍스트, depth 는 w2grid_groupby_depth_N 에서 추출
//  - 데이터 행 : 4개 Body 컬럼(_0.._3)을 이어붙임, depth 는 그룹 depth 수(depthCount) 기준
//  - 숨김 filler Row(w2grid_hidedRow / display:none) 제외 / nbsp→공백
scwin.readScreenLines = function (depthCount) {
    depthCount = depthCount || 0;
    let tbody = document.getElementById(target1.id + "_body_tbody");
    let trs = tbody.querySelectorAll("tr");
    let screenLines = [];
    for (let i = 0; i < trs.length; i++) {
        let tr = trs[i];
        if (tr.style.display === "none" || tr.className.indexOf("w2grid_hidedRow") >= 0) continue;
        let gtd = tr.querySelector("td.w2grid_groupby");
        if (gtd) {
            let rowDepth = depthCount;
            let dc = tr.querySelector("td[class*='w2grid_groupby_depth_']");
            if (dc) {
                let m = dc.className.match(/w2grid_groupby_depth_(\d+)/);
                if (m) rowDepth = parseInt(m[1], 10);
            }
            screenLines.push(scwin._depthMark(rowDepth) + (gtd.textContent || "").replace(/ /g, " ").trim());
        } else {
            let cells = [];
            for (let c = 0; c < 4; c++) {
                let td = tr.querySelector("td[id*='_cell_'][id$='_" + c + "']");
                cells.push(td ? (td.textContent || "").replace(/ /g, " ").trim() : "");
            }
            screenLines.push(scwin._depthMark(depthCount) + cells.join(" | "));
        }
    }
    return screenLines;
}

// Header 더블클릭 관찰 핸들러 : 사용자가 헤더를 더블클릭한 시점의 화면 순서를 결과창에 출력
//  - 동일 더블클릭 중복 전달을 디바운스로 1회만 출력, setTimeout(…,0) 으로 엔진 정렬 처리 후 순서 읽기
scwin.onHeaderDblclick = function () {
    let now = Date.now();
    if (scwin._lastHdrDbl && (now - scwin._lastHdrDbl) < 150) return;
    scwin._lastHdrDbl = now;
    setTimeout(function () {
        let grouped = !!(target1.groupbyStatus && target1.groupbyStatus.grouped);
        let depthCount = (grouped && target1.groupbyStatus.sortIndexArr) ? target1.groupbyStatus.sortIndexArr.length : 0;
        let sl = scwin.readScreenLines(depthCount);
        let head = grouped
            ? "[Header 더블클릭 관찰] 그룹 상태 : 헤더를 더블클릭해도 정렬되지 않고 화면 순서가 그대로 유지됩니다 (정렬 미동작)."
            : "[Header 더블클릭 관찰] 그룹 아님 : 헤더 더블클릭으로 정렬이 적용됩니다 (순서 변함).";
        wf_body_bottom.getObj("scwin").setReturnValue(head + "\n[화면 표시 순서]\n" + (sl.length ? sl.join("\n") : "(표시 Row 없음)"));
    }, 0);
}



// 그룹핑 확인 : 현재 그리드 표시값을 화면 순서(위→아래) 그대로 출력 + 표시 데이터행 수 (_1 과 동일 포맷)
//  - 필터 동작/미동작 대조 : 그룹핑 전 필터(부산 해제) 시 표시데이터행 감소(3), 그룹핑 후 기존 필터 해제로 전체 표시(6)
scwin.btn_check_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let grouped = !!(target1.groupbyStatus && target1.groupbyStatus.grouped);
    let depthCount = (grouped && target1.groupbyStatus.sortIndexArr) ? target1.groupbyStatus.sortIndexArr.length : 0;

    // 표시 데이터행 수(그룹행 제외) / 그룹행 수 집계
    let tbody = document.getElementById(target1.id + "_body_tbody");
    let trs = tbody ? tbody.querySelectorAll("tr") : [];
    let dataCnt = 0, groupCnt = 0;
    for (let i = 0; i < trs.length; i++) {
        let tr = trs[i];
        if (tr.style.display === "none" || tr.className.indexOf("w2grid_hidedRow") >= 0) continue;
        if (tr.querySelector("td.w2grid_groupby")) groupCnt++; else dataCnt++;
    }

    bottom.setReturnValue("[상태] 그룹핑=" + (grouped ? "적용" : "미적용")
        + " / 표시 데이터행=" + dataCnt + (grouped ? " (그룹행 " + groupCnt + ")" : "")
        + (grouped
            ? " → 그룹핑 후 기존 필터가 해제되어 전체 표시(필터 미동작)"
            : " (지역 필터로 부산 제외 시 감소 = 필터 동작)"));

    let sl = scwin.readScreenLines(depthCount);
    bottom.setReturnValue("[화면 표시 순서]\n" + (sl.length ? sl.join("\n") : "(표시 Row 없음)"));
}
